import os
import torch


class Config:
    """
    Global configuration for the Animal Classification pipeline.
    Handles paths, hyperparameters, and compute settings.
    """

    # ==========================================
    # Reproducibility
    # ==========================================
    SEED = 42

    # ==========================================
    # Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_2"
    SUBMISSION_DIR = "./submission"

    # Metadata Files (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Output Files
    # Best model weights will be saved here
    MODEL_CHECKPOINT_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    # Final submission file
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Compute Settings
    # ==========================================
    # Use CUDA if available, otherwise CPU
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # Number of workers for DataLoader (matches available vCPUs)
    NUM_WORKERS = 12
    # Pin memory for faster host-to-device transfer
    PIN_MEMORY = True

    # ==========================================
    # Data Parameters
    # ==========================================
    # ResNet standard input size
    IMAGE_SIZE = (224, 224)
    # Number of animal species + empty class
    NUM_CLASSES = 23
    # Batch size (A100 has 40GB VRAM, can handle large batches)
    BATCH_SIZE = 128

    # Debugging: Set to an integer (e.g., 5000) to limit dataset size.
    # Set to None to use the full dataset.
    DEBUG_SAMPLE_SIZE = None

    # ==========================================
    # Model Architecture
    # ==========================================
    BACKBONE = "resnet50"
    PRETRAINED = True

    # ==========================================
    # Training Hyperparameters
    # ==========================================

    # --- Stage 1: Linear Warmup ---
    # Optimizer: Adam
    # Goal: Fit the classifier head to the frozen backbone features
    STAGE1_EPOCHS = 5
    STAGE1_LR = 1e-3

    # --- Stage 2: Fine-Tuning ---
    # Optimizer: AdamW
    # Goal: Adapt high-level features (Layer 4) to the domain
    STAGE2_EPOCHS = 12
    STAGE2_LR = 1e-4
    STAGE2_WEIGHT_DECAY = 0.05

    # Early Stopping patience for Stage 2
    PATIENCE = 3

    @classmethod
    def setup(cls):
        """
        Initialize the environment by creating necessary directories.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Execute setup to ensure directories exist when module is imported
Config.setup()
